using Microsoft.EntityFrameworkCore;
namespace TheBarcode.Api;
public static class SeedData
{
 public static async Task Initialize(AppDbContext db,string bootstrapPin){await db.Database.EnsureCreatedAsync();if(await db.Staff.AnyAsync())return;var admin=new StaffUser{Name="Admin",Role="Owner",PinHash=Security.HashPin(bootstrapPin)};db.Staff.Add(admin);db.Products.AddRange(new Product[]{new(){Name="Tusker Lager",Category="Beer",Barcode="616110000001",Unit="500ml bottle",CostPrice=230,SellingPrice=320,Stock=96,MinStock=24},new(){Name="White Cap",Category="Beer",Barcode="616110000002",Unit="500ml bottle",CostPrice=250,SellingPrice=350,Stock=84,MinStock=24},new(){Name="Jameson",Category="Spirits",Barcode="5011007003005",Unit="750ml bottle",CostPrice=2850,SellingPrice=3800,Stock=18,MinStock=5},new(){Name="Cappuccino",Category="Coffee",Unit="300ml serving",CostPrice=95,SellingPrice=280,Stock=80,MinStock=15},new(){Name="Beef Burger",Category="Food",Unit="serving",CostPrice=280,SellingPrice=650,Stock=22,MinStock=12},new(){Name="Fresh Milk",Category="Kitchen",Unit="litre",CostPrice=110,SellingPrice=0,Stock=12,MinStock=8,Sellable=false},new(){Name="Passion Juice",Category="Soft Drinks",Unit="400ml serving",CostPrice=85,SellingPrice=220,Stock=18,MinStock=20}});db.Customers.AddRange(new Customer{Name="Walk-in",CreditLimit=0},new Customer{Name="Brian Otieno",Phone="254712345678",CreditLimit=5000},new Customer{Name="Mercy Njeri",Phone="254798111222",CreditLimit=8000});db.AuditEvents.Add(new AuditEvent{StaffId=admin.Id,Actor=admin.Name,Action="Seeded",EntityType="System",Details="Created initial business data",DeviceId="server"});await db.SaveChangesAsync();}
}
